namespace CCOS.Data.Entities;

/// <summary>
/// A member's current officer title. Having this row is what gives officer access in the app,
/// as long as the member is also current (CAR-28). OfficerId is the same number as the MemberId.
/// Past titles live in OfficerHistory.
/// </summary>
public class Officer
{
    /// <summary>Same value as Member.MemberId (not generated by the database).</summary>
    public int OfficerId { get; set; }

    /// <summary>The title, like President or Treasurer.</summary>
    public string Title { get; set; } = null!;

    public DateOnly GrantedDate { get; set; }

    /// <summary>
    /// Which admin granted the title. Not linked to a table yet: the Admins table comes in
    /// CAR-74, so this stays empty until then.
    /// </summary>
    public int? GrantedByAdminId { get; set; }

    public Member Member { get; set; } = null!;
}
